with prev_events as (select *, lag(event_time) over (partition by page order by event_time, id) as prev_event_time from web_events), with_gaps as (select *, case when prev_event_time is null or event_time > prev_event_time + interval '60' day then 1 else 0 end as new_group_flag from prev_events), sessionized as (select *, sum(new_group_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as island_id from with_gaps) select case when new_group_flag >= 1 then 'HIGH' else 'LOW' end as new_group_flag_tier, session_id, bit_and(duration_sec) as duration_sec_bit_and, min(event_time) as first_seen, count_if(event_type = 'search') as search_events from sessionized group by new_group_flag_tier, session_id having count_if(event_type = 'search') >= 1;
